extends SmokeTestBase

const SCENES := [
	"res://scenes/main.tscn",
	"res://scenes/boot.tscn",
	"res://scenes/debug_overlay.tscn",
	"res://scenes/benchmark_noop.tscn",
]


func test_all_scenes_instantiate_with_working_scripts() -> void:
	for path in SCENES:
		var packed: PackedScene = load(path)
		ok(packed != null, "%s loads" % path)
		if packed == null:
			continue
		var node := packed.instantiate()
		ok(node != null, "%s instantiates" % path)
		if node == null:
			continue
		var script := node.get_script() as GDScript
		if script != null:
			ok(script.can_instantiate(), "%s root script compiles" % path)
		node.free()

extends SmokeTestBase


## Compile smoke for every script in the project. Scene instantiation alone
## does NOT catch GDScript compile failures (a broken script still yields a
## node), so this suite loads each .gd directly and requires it to be
## instantiable (all our scripts are tool-free RefCounted/Node classes).

func test_all_scripts_compile() -> void:
	var files: PackedStringArray = []
	_collect_scripts("res://", files)
	ok(files.size() >= 14, "expected the full script set (found %d)" % files.size())
	for path in files:
		var script: GDScript = load(path)
		ok(script != null and script.can_instantiate(), "%s compiles" % path)


func _collect_scripts(dir_path: String, out: PackedStringArray) -> void:
	var dir := DirAccess.open(dir_path)
	if dir == null:
		return
	dir.list_dir_begin()
	var entry := dir.get_next()
	while entry != "":
		var full := dir_path.path_join(entry)
		if dir.current_is_dir():
			if not entry.begins_with("."):
				_collect_scripts(full, out)
		elif entry.ends_with(".gd") and not full.begins_with("res://tests/"):
			out.append(full)
		entry = dir.get_next()
	dir.list_dir_end()

