extends RefCounted
class_name MetricsCollector
## Machine-readable per-instance metrics. Written as JSON at shutdown and
## printed as a single METRICS_JSON line for harness capture.

var role := ""
var extra := {}
var _counters := {}
var _samples := {}      # name -> Array[float]
var _byte_counters := {}
var _timeline := []     # [{t_ms, event}]
var _start_ms := 0


func setup(p_role: String) -> void:
	role = p_role
	_start_ms = Time.get_ticks_msec()


func count(name: String, by := 1) -> void:
	_counters[name] = int(_counters.get(name, 0)) + by


func add_bytes(name: String, n: int) -> void:
	_byte_counters[name] = float(_byte_counters.get(name, 0.0)) + float(n)


func sample(name: String, value: float) -> void:
	if not _samples.has(name):
		_samples[name] = []
	_samples[name].append(value)


func event(name: String) -> void:
	_timeline.append({"t_ms": Time.get_ticks_msec() - _start_ms, "event": name})


func ping(rtt_ms: float) -> void:
	sample("rtt_ms", rtt_ms)


func _summarize_samples() -> Dictionary:
	var out := {}
	for k in _samples:
		var arr: Array = _samples[k]
		if arr.is_empty():
			continue
		var sorted := arr.duplicate()
		sorted.sort()
		out[k] = {
			"n": arr.size(),
			"avg": snappedf(_avg(arr), 0.001),
			"p95": snappedf(sorted[int(mini(sorted.size() - 1, int(sorted.size() * 0.95)))], 0.001),
			"max": snappedf(sorted[-1], 0.001),
		}
	return out


func _avg(arr: Array) -> float:
	var s := 0.0
	for v in arr:
		s += v
	return s / maxf(1.0, float(arr.size()))


func to_dict() -> Dictionary:
	return {
		"role": role,
		"engine": Engine.get_version_info().string,
		"netfox": "1.35.3",
		"uptime_sec": (Time.get_ticks_msec() - _start_ms) / 1000.0,
		"counters": _counters,
		"bytes": _byte_counters,
		"samples": _summarize_samples(),
		"timeline": _timeline,
		"extra": extra,
	}


func dump(path: String) -> void:
	var d := to_dict()
	var text := JSON.stringify(d, "  ")
	print("METRICS_JSON ", JSON.stringify(d))
	if path != "":
		var f := FileAccess.open(path, FileAccess.WRITE)
		if f:
			f.store_string(text)
			f.close()


func net_perf_snapshot() -> void:
	count("netperf_poll")
	var np: Node = (Engine.get_main_loop() as SceneTree).root.get_node_or_null(^"NetworkPerformance")
	if np == null:
		return
	sample("net_loop_ms", np.get_network_loop_duration_ms())
	sample("rollback_loop_ms", np.get_rollback_loop_duration_ms())
	sample("rollback_tick_ms", np.get_rollback_tick_duration_ms())
